import json,pathlib,numpy as np
A=json.load(open('submission_fits.json'));pathlib.Path('models').mkdir(exist_ok=True)
common_data="`data/train.csv`, all three trajectories. The final simulation criterion uses all 447 within-trajectory transitions, never crossing experiment boundaries. Auxiliary lag fits use 444 transitions: the first transition of each trajectory is omitted because its previous input is unknown. Previous logged inputs are used only during estimation; the delivered expressions do not use history. No test data were accessed."
common_limit="The units and physical system are not supplied. Equal coordinate scales for `y` and `x1`, and an angular interpretation of `x2` in radians, are inferred modelling assumptions, not supplied facts. Only three short trajectories are available; numerical input ranges and initial conditions outside the logged experiments are not validated. Residuals indicate input-change transients with memory missing from the permitted state vector. The memoryless expressions cannot reproduce these exactly. The phase correction is an effective numerical correction, not an identified actuator time constant. Wrapping `x2_next` with `atan2(sin(...),cos(...))` prevents a discontinuity from being treated as a large rotation, but the output coordinates can still drift during long simulations."
common_origin="Affine and degree-two and degree-three polynomial increment regressions were tried first, using ordinary least squares and leave-one-trajectory-out simulation; they extrapolated poorly or diverged and were excluded. Nearly longitudinal displacement after rotation by `x2` motivated trigonometric kinematics; this is an empirical structural inference rather than a supplied physical law. Large residuals at input changes motivated auxiliary current/previous-input regressions. Absolute-value contrasts, dead zones, smooth friction and input interactions were then compared. No genetic-programming symbolic-regression package was used."
ref="Discrete-time unicycle-like kinematic model. A relevant general reference is Murray, Li and Sastry, A Mathematical Introduction to Robotic Manipulation (1994), cited from memory, not verified online."

def row(name,value,desc,unit='unknown; column units not supplied',type='fitted',equation=None):
 r=dict(name=name,value=float(value),unit=unit,type=type,description=desc)
 if equation is not None:r['equation']=equation
 return r

def make(label):
 r=A[label];p=r['p'];pars=[]
 if label=='CoupledDeadzone':
  names=['a','d','l','c','e','m'];v="a*(sign(x3+l*x4)*Max(Abs(x3+l*x4)-d,0)+sign(x3-l*x4)*Max(Abs(x3-l*x4)-d,0))/2";h="c*(sign(x3+l*x4)*Max(Abs(x3+l*x4)-d,0)-sign(x3-l*x4)*Max(Abs(x3-l*x4)-d,0))+e"
  desc=["Gain `a` multiplying the mean of the two transformed input channels.","Dead-zone threshold `d` of each transformed input channel, estimated from data.","Input mixing coefficient `l` in `x3+l*x4` and `x3-l*x4`; not a known physical length.","Gain `c` multiplying the difference of the transformed channels in the angular increment.","Additive angular increment `e` per sample.","Dimensionless phase fraction `m` in the trigonometric position update; allows a negative effective phase to compensate missing lag."]
  family=ref+" Its static response is a coupled dead-zone Hammerstein-type nonlinearity followed by kinematic integration, not a full Hammerstein model with additional dynamic states."
  origin=common_origin+" The two input combinations and a shared dead-zone threshold were a structural hypothesis to represent weak angular response when one transformed channel is close to zero. The coupling makes both coordinate displacement and rotation depend on the same transformed channels. The numerical mixing coefficient was estimated; no wheel geometry was assumed."
  interpretation="Define explanatory channel values `L = sign(x3-l*x4)*Max(Abs(x3-l*x4)-d,0)` and `R = sign(x3+l*x4)*Max(Abs(x3+l*x4)-d,0)`. These names are explanatory only, not extra model states. The signed dead zones suppress small channel magnitudes. Define longitudinal displacement `V = a*(L+R)/2` and angular increment `H = c*(R-L)+e`; their mean and difference provide a compact coupled-input response. The position increments are `V*cos(x2+m*H)` and `V*sin(x2+m*H)`. The inferred heading is advanced by `H` and wrapped. No physical interpretation of the channels or coefficients is claimed."
 elif label=='SmoothAngular':
  names=['a','b','c','d','s','e','m'];v='a*x3+b';h='c*x4-d*tanh(x4/s)+e'
  desc=["Longitudinal input gain `a`.","Longitudinal increment offset `b` per sample.","Linear angular input gain `c`.","Magnitude `d` of the saturating correction to the angular response.","Positive input scale `s` setting the smooth correction transition width.","Angular increment offset `e` per sample.","Dimensionless phase fraction `m` in the coordinate update."]
  family=ref+" The angular response is a smooth friction-like static nonlinearity, linear gain minus a hyperbolic-tangent term; the friction name describes its mathematical shape, not a known physical mechanism."
  origin=common_origin+" An angular offset-plus-linear-gain model left input-magnitude-dependent residuals. The term `-d*tanh(x4/s)` was a proposed smooth, odd correction to suppress small angular commands while approaching a constant subtraction at large magnitudes. The width was fitted rather than chosen from a physical friction law. The longitudinal affine law was retained because its additional nonlinearities gave little reliable benefit."
  interpretation="Define explanatory longitudinal displacement `V = a*x3+b` and angular increment `H = c*x4-d*tanh(x4/s)+e`. The first is an affine input response. The linear angular term controls the large-input slope; the hyperbolic-tangent term reduces the response with a smooth transition governed by `s`; `e` adds an angular bias. Position increments are `V*cos(x2+m*H)` and `V*sin(x2+m*H)`. The angle update is `atan2(sin(x2+H),cos(x2+H))`. These are mathematical roles, not confirmed physical meanings."
 elif label=='AbsoluteCoupling':
  names=['a','b','c','d','l','e','m'];v='a*x3+b';h='c*x4+d*(Abs(x3-l*x4)-Abs(x3+l*x4))+e'
  desc=["Longitudinal input gain `a`, estimated in the auxiliary lag regression.","Longitudinal increment offset `b`, estimated in the auxiliary lag regression.","Angular linear gain `c`, the sum of current and previous angular-input coefficients.","Angular absolute-contrast gain `d`, the sum of current and previous contrast coefficients.","Fixed mixing scale `l = 0.1`, a heuristic structural scale suggested by the relative magnitudes of the logged inputs; not a measured geometric quantity. It was not optimized for this candidate.","Angular increment offset `e`, the intercept of the auxiliary angular regression.","Effective dimensionless phase fraction `m`, tied to fitted geometric arc fraction and auxiliary delay fraction."]
  family=ref+" Its angular static map is a continuous piecewise-affine coupled-input model represented by absolute values."
  origin=common_origin+" The absolute-value contrast was suggested by a trial feature library of transformed input channels. A fixed mixing scale was deliberately retained: allowing it to vary with trajectory-level fitting produced less reliable held-out predictions. Unlike the shared dead-zone candidate, the longitudinal response here remains independent and affine."
  interpretation="Define explanatory `V = a*x3+b` and `H = c*x4+d*(Abs(x3-l*x4)-Abs(x3+l*x4))+e`. The contrast term is continuous and changes slope on `x3-l*x4 = 0` or `x3+l*x4 = 0`; it permits angular response to depend on longitudinal input without a high-degree polynomial. Position increments are `V*cos(x2+m*H)` and `V*sin(x2+m*H)`. `arc` is the fitted local side-displacement fraction and `delay` is the fitted previous-input blending fraction; `m = arc-delay` is an effective lag compensation. Neither is an additional model state."
 else:
  names=['a','b','c','d','m'];v='a*x3+b';h='c*x4+d'
  desc=["Longitudinal input gain `a` from the auxiliary current/previous-input fit.","Longitudinal increment offset `b` from that same fit.","Angular input gain `c` from the auxiliary current/previous-input fit.","Angular increment offset `d` from that same fit.","Dimensionless phase fraction `m`, tied to an assumed local arc fraction minus a fitted input delay fraction."]
  family=ref+" The static longitudinal and angular responses are affine, providing the lowest-complexity retained baseline."
  origin=common_origin+" This baseline preserves only affine input responses, coordinate rotation and angle wrapping. Unregularized trajectory fitting worsened held-out performance, so this candidate uses the reduced static gain from a lag-aware one-step fit, not a position-dependent correction. It is retained as a low-complexity alternative, although the residuals support nonlinear response."
  interpretation="Define explanatory `V = a*x3+b` and `H = c*x4+d`. Offsets and gains allow affine longitudinal displacement and angular increment. Rotation by `x2+m*H` converts displacement to the two coordinates. The phase uses `m = arc-delay`, where `arc` is an assumed local arc fraction and `delay` is an auxiliary fitted previous-input fraction. The latter is not a new dynamic state."
 for nm,val,de in zip(names,p,desc):
  ty='fixed' if label=='AbsoluteCoupling' and nm=='l' else 'fitted';un='-' if nm=='m' else 'unknown; column units not supplied'
  if nm=='m' and label in ['AbsoluteCoupling','LinearKinematic']:ty='tied'
  pars.append(row(nm,val,de,un,ty,'arc-delay' if ty=='tied' else None))
 if label=='AbsoluteCoupling':
  pars+= [row('arc',r['arc'],"Local arc fraction `arc`, fitted by ordinary least squares of observed rotated side displacement on a constant and the product of forward displacement and angular increment, using the 267 transitions whose within-block phase is at least two.",'-'),row('delay',r['delay'],"Delay fraction `delay`, estimated by scalar ordinary least squares of angular residual on the difference of previous and current static-map predictions, using the 444 auxiliary transitions.",'-')]
 elif label=='LinearKinematic':
  pars+=[row('arc',.45,"Assumed local arc fraction `arc = 0.45`, chosen as a rounded approximation to the steady-phase least-squares estimate `0.4480684583258992` on 267 training transitions; not optimized within this candidate. It sets the phase-compensation convention.",'-','fixed'),row('delay',r['lag'][1],"Auxiliary angular delay fraction `delay`, jointly fitted with the static response using current and previous logged inputs.",'-')]
 expressions={'y_next':f'y + ({v})*cos(x2+m*({h}))','x1_next':f'x1 + ({v})*sin(x2+m*({h}))','x2_next':f'atan2(sin(x2+({h})),cos(x2+({h})))'}
 if label=='AbsoluteCoupling':
  criterion="Two ordinary least-squares auxiliary criteria: squared residuals of observed body-frame forward displacement on a constant, current `x3` and previous `x3`; and squared residuals of unwrapped angular increment on a constant, current and previous `x4`, and current and previous absolute-input contrasts. These separate the systematic lag effect from the effective static gain. The arc and delay fractions are then obtained by the two scalar regression criteria described in their parameter rows."
  method="Ordinary least squares using `numpy.linalg.lstsq`; no initial values or random seeds are needed because all four regressions are linear in their fitted coefficients. First fit the two lag-aware regressions independently, then sum corresponding current and previous coefficients to obtain effective static gains; the intercepts are retained. `l = 0.1` is fixed before these regressions. Next estimate `arc` with the stated steady-phase regression. Finally estimate `delay` as the scalar projection of observed angular residual onto the difference of previous and current static-map predictions; set `m = arc-delay`. This staged reduction is used because missing input memory otherwise biases direct one-step regression."
 else:
  f=r['family'];init=INITS[f] if False else {'deadwheel':[.18,.015,.08,.91,0,-.25],'smoothyaw':[.169,0,.16,.014,.08,-.0003,-.25],'affineyaw':[.169,0,.137,0,-.25]}[f]
  criterion="First minimize squared one-step residuals of body-frame forward displacement and unwrapped angular increment with auxiliary current/previous-input blends, normalized by `0.003` in unspecified coordinate units and `0.02` radians respectively. These scales were chosen from preliminary training residual magnitudes to balance the channels."
  method="Bounded nonlinear least squares using `scipy.optimize.least_squares`, the trust-region reflective method with linear loss, because the static nonlinearity and input-delay blends are nonlinear in their coefficients. No random numbers or seeds are used. The auxiliary initial static vector, in the parameter order of the candidate, is `"+str(init)+"`; its coefficients have their respective unspecified units and the last phase coordinate is dimensionless. Initial dimensionless forward and angular previous-input fractions are `0.28` and `0.7`. The phase coordinate does not enter the auxiliary criterion and is not identified there; it is replaced by `0.45` minus the fitted angular delay fraction. All other auxiliary coordinates are fitted together. Auxiliary fits use at most 1200 function evaluations; all three termination tolerances are `1e-10`."
  if label=='LinearKinematic':
   criterion+=" The final static coefficients are those from this fit, without trajectory-level refinement; the phase is tied to the auxiliary delay to compensate the memory removed from the final model."
   method+=" No trajectory-level refinement is used, because the tested unregularized refinement degraded leave-one-trajectory-out simulations. `m = arc-delay` is computed after fitting; `arc` is fixed."
  else:
   w=r['weight'];criterion+=" Then minimize free-running squared errors of `y` and `x1`, plus squared unwrapped angular errors multiplied by `0.04`. Add squared deviations from the auxiliary static forward and angular responses, with residual multipliers `"+str(10*w)+"` and `"+str(w)+"` respectively, and a squared phase-deviation residual with multiplier `"+str(.02*w)+"`. These are numerical balancing factors, not physical unit conversions. The state criterion avoids long-run accumulation being ignored, and the static-map penalty limits trajectory overfitting."
   method+=" All final fitted parameters are then refined together, starting from the auxiliary vector `"+str(r['p0'])+"` in the same parameter order. Refinement uses at most 1000 function evaluations and the same tolerances. Bound constraints and exact residual computations are in `refine.py`; gains and widths are kept positive and `-1 <= m <= 1`. The regularization multiplier `"+str(w)+"` was chosen from the tested numerical grid `0, 2, 4, 8, 12, 16, 24, 40` by pooled leave-one-trajectory-out `y` RMSE within this family. Each validation fit used only the other two trajectories, including recomputing its auxiliary reference. The final fit uses all three. This is selection on very limited validation data, not an independent performance guarantee."
 stats=" Training free-running `y` RMSE is `"+format(r['pooled_train_y'],'.6g')+"`; pooled leave-one-trajectory-out `y` RMSE is `"+format(r['pooled_cv_y'],'.6g')+"`, both in unspecified `y` units and computed after the first sample of each training trajectory. One-step angular RMSE immediately after a five-sample input-block boundary is `"+format(r['phase0_rmse'][2],'.6g')+"` radians versus `"+format(r['other_phase_rmse'][2],'.6g')+"` radians at other phases, on the 447 training transitions. This supports the missing-memory limitation."
 out=dict(expressions=expressions,parameters=pars,estimation=dict(criterion=criterion,data=common_data,method=method,script='fit_submission.py'),discussion=dict(family=family,interpretation=interpretation,origin=origin,limitations=common_limit+stats))
 json.dump(out,open('models/'+label+'.json','w'),indent=2)
for lab in A:make(lab)
order=['CoupledDeadzone','SmoothAngular','AbsoluteCoupling','LinearKinematic']
pool=dict(order=order,recommended='CoupledDeadzone',reason="`CoupledDeadzone` has the lowest pooled leave-one-trajectory-out free-running `y` RMSE among the retained structurally different families: `0.115160` versus `0.127536` for `SmoothAngular`, `0.142038` for `AbsoluteCoupling` and `0.212931` for `LinearKinematic`, all in unspecified `y` units on the three training trajectories. The nonlinear coupled-input response is supported by residual structure and its static-map regularization limits path-specific fitting. `SmoothAngular` fits training paths better and remains a useful alternative. With only three validation trajectories and apparent missing input memory, the ranking is uncertain and is not a claim about unavailable test performance.")
json.dump(pool,open('models/pool.json','w'),indent=2)
